CREATE TABLE `regions` (`REGION_ID` DECIMAL(18,2), `REGION_NAME` VARCHAR(100));
CREATE TABLE `countries` (`COUNTRY_ID` VARCHAR(100), `COUNTRY_NAME` VARCHAR(100), `REGION_ID` DECIMAL(18,2));
CREATE TABLE `departments` (`DEPARTMENT_ID` DECIMAL(18,2), `DEPARTMENT_NAME` VARCHAR(100), `MANAGER_ID` DECIMAL(18,2), `LOCATION_ID` DECIMAL(18,2));
CREATE TABLE `jobs` (`JOB_ID` VARCHAR(100), `JOB_TITLE` VARCHAR(100), `MIN_SALARY` DECIMAL(18,2), `MAX_SALARY` DECIMAL(18,2));
CREATE TABLE `employees` (`EMPLOYEE_ID` DECIMAL(18,2), `FIRST_NAME` VARCHAR(100), `LAST_NAME` VARCHAR(100), `EMAIL` VARCHAR(100), `PHONE_NUMBER` VARCHAR(100), `HIRE_DATE` DATETIME, `JOB_ID` VARCHAR(100), `SALARY` DECIMAL(18,2), `COMMISSION_PCT` DECIMAL(18,2), `MANAGER_ID` DECIMAL(18,2), `DEPARTMENT_ID` DECIMAL(18,2));
CREATE TABLE `job_history` (`EMPLOYEE_ID` DECIMAL(18,2), `START_DATE` DATETIME, `END_DATE` DATETIME, `JOB_ID` VARCHAR(100), `DEPARTMENT_ID` DECIMAL(18,2));
CREATE TABLE `locations` (`LOCATION_ID` DECIMAL(18,2), `STREET_ADDRESS` VARCHAR(100), `POSTAL_CODE` VARCHAR(100), `CITY` VARCHAR(100), `STATE_PROVINCE` VARCHAR(100), `COUNTRY_ID` VARCHAR(100));
